import api from './api';
import axios from 'axios';

const API_URL = "http://localhost:5000/api/stock";

// Consolidated stock service functions
export const stockService = {
  getStock: async (params = {}) => {
    try {
      const response = await api.get('/stock', { params });
      return response.data;
    } catch (error) {
      console.error("Error fetching stock:", error.response?.data || error.message);
      throw error;
    }
  },

  addStockTransaction: async (data) => {
    try {
      const response = await axios.post(API_URL, data);
      return response.data;
    } catch (error) {
      console.error("Error adding stock:", error.response?.data || error.message);
      throw error;
    }
  },

  getStockSummary: async () => {
    try {
      const response = await api.get('/stock/summary');
      return response.data || { totalValue: 0, items: [] };
    } catch (error) {
      console.error("Error fetching stock summary:", error.response?.data || error.message);
      return { totalValue: 0, items: [] }; // Return empty data if API fails
    }
  }
};

